sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    var _patientDetails = new PatientUtils();

    var _patientInfo = _patientDetails.fetchAllPatientDetailsByPatientId('PAT0001027');
    gs.print(_patientInfo.u_first_name + ' ' + _patientInfo.u_last_name);

    var checkVip = _patientDetails.checkIfPatientIsVip('PAT0001027');
    gs.print(checkVip);

    var patientAge = _patientDetails.calculatePatientAge('PAT0001027');
    gs.print(patientAge);

    var _patinetAppt = _patientDetails.fetchPatientAppointments('0214c8f093626610ec38b2ddfaba105e')
    if (!_patinetAppt.hasNext()) {
        gs.print("No appointments found for patient.");
    } else {
        while (_patinetAppt.next()) {
            gs.print("-----Appointment-----")
            gs.print("Appointment Date: " + _patinetAppt.u_appointment_date);
            gs.print("Doctor: " + _patinetAppt.u_doctor.getDisplayValue());
            gs.print("Status: " + _patinetAppt.u_statis);
            gs.print("-----");
        }
    }

    var _patientMedication = _patientDetails.fetchPatientMedications('0214c8f093626610ec38b2ddfaba105e');
    if (!_patientMedication.hasNext()) {
        gs.print("No medication found for patient.");
    } else {
        while (_patientMedication.next()) {
            gs.print("-----Medication-----")
            gs.print("Medication Date: " + _patientMedication.u_medication_name);
            gs.print("Dosage: " + _patientMedication.u_dosage);
            gs.print("frequency: " + _patientMedication.u_frequency);
            gs.print("-----");
        }
    }


    var _patientLabTest = _patientDetails.fetchPatientLabTest('0214c8f093626610ec38b2ddfaba105e');
    if (!_patientLabTest.hasNext()) {
        gs.print("No Lab Test found for patient.");
    } else {
        while (_patientLabTest.next()) {
            gs.print("-----LabTest-----")
            gs.print("Scheduled Date: " + _patientLabTest.u_scheduled_date);
            gs.print("Status: " + _patientLabTest.u_status);
            gs.print("Test Type: " + _patientLabTest.u_test_type);
            gs.print("-----");
        }
    }

    var _patientBilling = _patientDetails.fetchPatientBillingRecord('0214c8f093626610ec38b2ddfaba105e')
    if (!_patientBilling.hasNext()) {
        gs.print("No Biiling Record found for patient.");
    } else {
        while (_patientBilling.next()) {
            gs.print("-----Billing-----")
            gs.print("Total Ammount: " + _patientBilling.u_total_ammount);
            gs.print("Status: " + _patientBilling.u_status);
            gs.print("Appointment ID: " + _patientBilling.number.getDisplayValue());
            gs.print("-----");
        }
    }


    var _patientInsurance = _patientDetails.fetchPatientInsurancePolicies('0214c8f093626610ec38b2ddfaba105e');
    if (!_patientInsurance.hasNext()) {
        gs.print("No Insurance found for patient.");
    } else {
        while (_patientInsurance.next()) {
            gs.print("-----Insurance-----")
            gs.print("Provider: " + _patientInsurance.u_provider);
            gs.print("Status: " + _patientInsurance.u_status);
            gs.print("Policy Number" + _patientInsurance.u_policy_number);
            gs.print("-----");
        }
    }

})(current, previous);
